questionvariables.text:
/* Four invertible (strictly monotonic) functions and four that fail the horizontal line test */
cfn1:x^3;
cfn2:atan(x);
cfn3:(1/2)^x;
cfn4:-x^5;
wfn1:x^2-1;
wfn2:(x-1)*x*(x+1);
wfn3:1/x^2;
wfn4:cos(x);
xmax:3;
ymax:3;
cplot1:plot(cfn1,[x,-xmax,xmax],[y,-ymax,ymax],[box, false],[yx_ratio, 1],[axes, solid]);
cplot2:plot(cfn2,[x,-xmax,xmax],[y,-%pi/2,%pi/2],[box, false],[yx_ratio, 1],[axes, solid]);
cplot3:plot(cfn3,[x,-xmax,xmax],[y,0,ymax],[box, false],[yx_ratio, 1],[axes, solid]);
cplot4:plot(cfn4,[x,-xmax,xmax],[y,-ymax,ymax],[box, false],[yx_ratio, 1],[axes, solid]);
wplot1:plot(wfn1,[x,-xmax,xmax],[y,-1,ymax],[box, false],[yx_ratio, 1],[axes, solid]);
wplot2:plot(wfn2,[x,-xmax,xmax],[y,-ymax,ymax],[box, false],[yx_ratio, 1],[axes, solid]);
wplot3:plot(wfn3,[x,-xmax,xmax],[y,0,ymax],[box, false],[yx_ratio, 1],[axes, solid]);
wplot4:plot(wfn4,[x,-xmax,xmax],[y,-1,1],[box, false],[yx_ratio, 1],[axes, solid]);
/* Each entry: [plot, formula] */
corbase:[[cplot1,cfn1],[cplot2,cfn2],[cplot3,cfn3],[cplot4,cfn4]];
wrongbase:[[wplot1,wfn1],[wplot2,wfn2],[wplot3,wfn3],[wplot4,wfn4]];
/* Two invertible and two non-invertible options; each opts entry is [plot, correct?, formula] */
sel_cor: maplist(lambda([ex], [ex[1], true, ex[2]]), rand_selection(corbase, 2));
sel_incorr: maplist(lambda([ex], [ex[1], false, ex[2]]), rand_selection(wrongbase, 2));
opts: random_permutation(append(sel_cor,sel_incorr));
/* Option values are static literal strings */
talab: ["(a)","(b)","(c)","(d)"];
ta1:zip_with(lambda([ex1, ex2], [ex1, ex2[2], sconcat("<b>", ex1, "</b> ", ex2[1])]), talab, opts);
version: map(lambda([o], o[3]), opts);
corr1:mcq_correct(ta1);
incorr1:mcq_incorrect(ta1);
/* Positions of the invertible and non-invertible graphs, for the worked solution */
lbls: [a,b,c,d];
pc: sublist_indices(opts, lambda([o], o[2]));
pw: sublist_indices(opts, lambda([o], not(o[2])));
